"""Writes crates/calc/tests/fixtures/origin_t81_data.rs: the data and Origin 2016's numbers of the partial correlation and
three-way and repeated measures ANOVA runs (T81), taken from t81-origin.compact.json. usage: python t81-make-fixture-rs.py OUT.rs"""
import json, sys

d = json.load(open(__file__.replace('t81-make-fixture-rs.py', 't81-origin.compact.json')))
out = ['// Generated by tools/origin-ref/stats6/t81-make-fixture-rs.py from t81-origin.compact.json (Origin 2016 runs).',
       '// Do not edit by hand.', '']


def num(v):
    if v is None:
        return 'f64::NAN'
    s = repr(float(v))
    return s


def txt(v):
    return 'f64::NAN' if v in ('--', None) else str(float(v))


out.append('/// One partial correlation run: columns, variable and control indices, listwise, one-tailed, r, p, df (row-major).')
out.append('pub struct PcRun {')
out.append('    pub name: &\'static str,')
out.append('    pub columns: Vec<Vec<f64>>,')
out.append('    pub vars: Vec<usize>,')
out.append('    pub controls: Vec<usize>,')
out.append('    pub listwise: bool,')
out.append('    pub one_tailed: bool,')
out.append('    pub r: Vec<f64>,')
out.append('    pub p: Vec<f64>,')
out.append('    pub df: Vec<f64>,')
out.append('}')
out.append('')
out.append('pub fn pc_runs() -> Vec<PcRun> {')
out.append('    vec![')
for k, v in d['pcorrcoef'].items():
    cols = ', '.join('vec![' + ', '.join(num(x) for x in c) + ']' for c in v['data'])
    flat = lambda m: ', '.join(txt(x) for row in m for x in row)
    out.append(f'        PcRun {{ name: "{k}", columns: vec![{cols}], vars: vec!{v["vars"]}, controls: vec!{v["controls"]}, '
               f'listwise: {str(v["missing"] == "listwise").lower()}, one_tailed: {str(v["tail"] == "one").lower()}, '
               f'r: vec![{flat(v["r"])}], p: vec![{flat(v["p"])}], df: vec![{flat(v["df"])}] }},')
out.append('    ]')
out.append('}')
out.append('')
out.append('/// A three-way run: level numbers (from 0) of A, B, C, the data, and the printed table `(term, df, SS, MS, F, p)`.')
out.append('pub struct A3Run {')
out.append('    pub a: Vec<usize>,')
out.append('    pub b: Vec<usize>,')
out.append('    pub c: Vec<usize>,')
out.append('    pub y: Vec<f64>,')
out.append('    pub table: Vec<(&\'static str, f64, f64, f64, f64, f64)>,')
out.append('}')
out.append('')
for k, v in d['anova3'].items():
    rows = v['rows']
    tab = []
    for t in v['table']:
        if t['df'] is None:
            continue
        g = lambda x: txt(x)
        tab.append(f'("{t["term"]}", {g(t["df"])}, {g(t["ss"])}, {g(t["ms"])}, {g(t["f"])}, {g(t["p"])})')
    out.append(f'pub fn a3_{k}() -> A3Run {{')
    out.append(f'    A3Run {{ a: vec!{[r[0] - 1 for r in rows]}, b: vec!{[r[1] - 1 for r in rows]}, c: vec!{[r[2] - 1 for r in rows]},')
    out.append(f'        y: vec!{[r[3] for r in rows]},')
    out.append(f'        table: vec![{", ".join(tab)}] }}')
    out.append('}')
    out.append('')
out.append('/// The one-way repeated measures run: 8 subjects (rows) by 4 levels.')
out.append('pub fn rm1_data() -> Vec<Vec<f64>> {')
out.append('    vec![' + ', '.join('vec!' + str([float(x) for x in r]) for r in d['rmanova1']['table']) + ']')
out.append('}')
out.append('')
subj = {}
for a, b, y, s in d['rmanova2']['rows_A_B_data_subject']:
    subj.setdefault(s, {})[(a, b)] = y
out.append('/// The two-way repeated measures run: 6 subjects (rows) by the 2 x 3 cells, factor A slowest.')
out.append('pub fn rm2_data() -> Vec<Vec<f64>> {')
out.append('    vec![' + ', '.join('vec!' + str([subj[s][(a, b)] for a in (1, 2) for b in (1, 2, 3)]) for s in sorted(subj)) + ']')
out.append('}')
out.append('')
open(sys.argv[1], 'w', encoding='utf8').write('\n'.join(out))
